"""Collect selected real test captures and build the implementation comparison after a passing release run."""
from pathlib import Path
import hashlib, html, json, shutil, struct

root = Path(__file__).resolve().parent
repo = root.parents[2]
validation = json.loads((root / 'implementation-validation.json').read_text())
assert validation['releaseChecksPassed'], 'Do not publish a completion comparison before release verification passes'
proof = root / 'implementation-proof'
proof.mkdir(exist_ok=True)
selected = [f'{area}-{lang}-{theme}-{width}.png' for lang, theme, width in [('cs','dark',1440),('en','light',360)] for area in ['work','settings','transactions','subscriptions','tasks','notes','prompts','dneskai-review','dneskai-sources','dneskai-mix','dneskai-music']]
evidence = []
for name in selected:
    matches = list((repo / 'test-results').glob(f'audit-implementation-*/{name}'))
    assert len(matches) == 1, (name, matches)
    source = matches[0]
    shutil.copyfile(source, proof / name)
    raw = source.read_bytes()
    width, height = struct.unpack('>II', raw[16:24])
    viewport_width = int(Path(name).stem.rsplit('-', 1)[1])
    scale = width / viewport_width
    evidence.append({'image': f'implementation-proof/{name}', 'source': str(source.relative_to(repo)), 'width': width, 'height': height, 'viewportWidth': viewport_width, 'viewportHeight': int(height / scale), 'deviceScaleFactor': scale, 'sha256': hashlib.sha256(raw).hexdigest(), 'kind': 'Actual optimized /dev-preview screenshot; synthetic fixtures; isolated Chromium'})
(root / 'implementation-evidence.json').write_text(json.dumps(evidence, indent=2) + '\n')
areas = [
 ('Work', 'Content-sized attention, dates and shipped work beside the planner.', 'work-cs-dark-1440.png', 'work-cs-dark-1440.png', 'U04 / U16'),
 ('Settings', 'Centered preferences, consistent controls and direct section navigation.', 'settings-cs-dark-1440.png', 'settings-cs-dark-1440.png', 'U05 / U07 / U08'),
 ('Transactions', 'Filters and records first; account/transaction creation and import on demand.', 'transactions-cs-dark-1440.png', 'transactions-cs-dark-1440.png', 'U06 / U15'),
 ('DNESKAi review', 'The selected revision comes before the bounded topic inbox. Full saved images still govern approval.', 'dneskai-lab-cs-dark-1440.png', 'dneskai-review-cs-dark-1440.png', 'U01 / U10'),
 ('Sources', 'Direct Sources / Daily mix / Music tabs, local search and source-kind filters.', 'dneskai-sources-cs-dark-1440.png', 'dneskai-sources-cs-dark-1440.png', 'U02 / U03 / U09'),
 ('Prompts', 'Sparse categories share masonry columns; each prompt has one preview/copy entry point.', 'prompts-cs-dark-1440.png', 'prompts-cs-dark-1440.png', 'U13'),
 ('Mobile Tasks', 'One filter summary with a dialog, clear-all and result count.', 'tasks-en-light-360.png', 'tasks-en-light-360.png', 'U07 / U08 / U11'),
]
for _,_,before,after,_ in areas:
    assert (root/'evidence'/before).exists(), before
    assert (proof/after).exists(), after
esc=html.escape
cards=''.join(f'''<section class="comparison" id="area-{i}"><div class="section-heading"><div><span class="meta">{esc(ids)}</span><h2>{esc(title)}</h2><p>{esc(description)}</p></div><a href="#top">Back to top ↑</a></div><div class="pair"><figure><figcaption>Before · audit baseline d6f60c7</figcaption><a href="evidence/{before}" target="_blank"><img src="evidence/{before}" alt="Before: {esc(title)}" loading="lazy"></a></figure><figure><figcaption>After · local implementation · actual fixture UI</figcaption><a href="implementation-proof/{after}" target="_blank"><img src="implementation-proof/{after}" alt="After: {esc(title)}" loading="lazy"></a></figure></div></section>''' for i,(title,description,before,after,ids) in enumerate(areas))
gallery=''.join(f'<a href="{esc(e["image"])}" target="_blank"><img loading="lazy" src="{esc(e["image"])}" alt="{esc(Path(e["image"]).stem)}"><span>{esc(Path(e["image"]).stem)} · viewport {e["viewportWidth"]} × {e["viewportHeight"]} · PNG {e["width"]} × {e["height"]}</span></a>' for e in evidence)
checks=''.join(f'<li><strong>{esc(check["name"])}</strong><span>{esc(check["result"])}</span></li>' for check in validation['checks'])
nav=''.join(f'<a href="#area-{i}">{esc(a[0])}</a>' for i,a in enumerate(areas))
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OwnDashboard — implemented audit changes</title><style>
:root{{color-scheme:light dark;--bg:#f5f5f7;--surface:#fff;--fg:#202124;--muted:#5d626a;--line:#d8dbe1;--link:#075eb4}}@media(prefers-color-scheme:dark){{:root{{--bg:#101214;--surface:#191c20;--fg:#ecedef;--muted:#abb1b9;--line:#343a42;--link:#92bfff}}}}*{{box-sizing:border-box}}html{{scroll-behavior:smooth;scroll-padding-top:1rem}}body{{margin:0;background:var(--bg);color:var(--fg);font:14px/1.6 -apple-system,BlinkMacSystemFont,system-ui,sans-serif}}a{{color:var(--link);text-underline-offset:3px}}a:focus-visible,button:focus-visible{{outline:3px solid var(--link);outline-offset:3px}}header,main,footer{{max-width:1320px;margin:auto;padding:24px}}header{{border-bottom:1px solid var(--line)}}.meta{{color:var(--muted);font-size:12px}}h1{{font-size:32px;line-height:1.2;margin:16px 0}}h2{{font-size:20px;margin:4px 0}}p{{margin:8px 0;max-width:85ch}}nav{{display:flex;flex-wrap:wrap;gap:8px 20px;margin-top:20px}}nav a{{display:inline-flex;min-height:44px;align-items:center}}.intro{{display:grid;grid-template-columns:1.2fr 1fr;gap:32px;margin:16px 0 40px}}.checklist{{list-style:none;padding:0;margin:0}}.checklist li{{display:flex;justify-content:space-between;gap:16px;border-bottom:1px solid var(--line);padding:10px 0}}.checklist span{{color:var(--muted);text-align:right}}.notice{{border-left:3px solid var(--link);padding:0 16px;margin:16px 0}}.comparison{{border-top:1px solid var(--line);padding-top:28px;margin-bottom:44px}}.section-heading{{display:flex;justify-content:space-between;gap:20px;align-items:start;margin-bottom:16px}}.pair{{display:grid;grid-template-columns:1fr 1fr;gap:20px}}figure{{margin:0;background:var(--surface);border:1px solid var(--line);border-radius:8px;overflow:hidden}}figcaption{{padding:10px 14px;font-size:12px;color:var(--muted);border-bottom:1px solid var(--line)}}figure img{{display:block;width:100%;height:auto;max-height:700px;object-fit:contain;object-position:top}}.gallery{{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}}.gallery a{{min-width:0;font-size:11px;overflow-wrap:anywhere}}.gallery img{{display:block;width:100%;height:180px;object-fit:contain;object-position:top;background:var(--surface);border:1px solid var(--line)}}.gallery span{{display:block;margin-top:6px}}footer{{color:var(--muted);border-top:1px solid var(--line)}}@media(max-width:760px){{header,main,footer{{padding:16px}}.intro,.pair{{grid-template-columns:1fr}}.gallery{{grid-template-columns:repeat(2,minmax(0,1fr))}}h1{{font-size:26px}}.section-heading{{display:block}}}}@media(prefers-reduced-motion:reduce){{html{{scroll-behavior:auto}}}}
</style></head><body><header id="top"><span class="meta">OwnDashboard / 23 October 2026 / local implementation</span><h1>Audit changes, implemented</h1><p>Seven correctness findings addressed, followed by shared UI, DNESKAi workflow and destination cleanup. These are real screenshots of the updated application, with synthetic preview data.</p><nav aria-label="Implementation comparisons">{nav}<a href="#verification">Verification</a><a href="index.html">Original review</a></nav></header><main><section class="intro" id="verification"><div><h2>Verified locally</h2><p>Application commit <code>{esc(validation['applicationCommit'])}</code> on <code>codex/dneskai-audit-implementation</code>.</p><p class="notice">Production is unchanged. Apply the prepared engagement-aggregate migration before deploying this code. This report is not proof of a live publisher run.</p><p>The Chrome extension was unavailable. Browser evidence uses isolated Chromium against the optimized fixture build; actual database behavior uses all migrations in local PostgreSQL/PGlite. Axe and keyboard checks do not replace a manual screen-reader audit.</p><p><a href="implementation-validation.json">Exact checks and limits</a> · <a href="implementation-performance.json">Payload, thumbnail and query measurements</a> · <a href="claude-kickoff.md">Claude handoff</a></p></div><ul class="checklist">{checks}</ul></section>{cards}<section><h2>More implemented states</h2><p class="meta">Click an actual capture to inspect it at its original size. Baseline and implementation captures can have different heights; the shown dimensions are recorded in the evidence manifest.</p><div class="gallery">{gallery}</div></section></main><footer>All seven fixes and all sixteen UX recommendations are mapped in the implementation report. Summary/detail reads, private derivatives and a new index remain measured experiments; they were not rolled out. <a href="implementation-evidence.json">Capture provenance</a>.</footer></body></html>'''
(root/'implementation.html').write_text(page)
print(f'Built implementation.html with {len(areas)} comparisons and {len(evidence)} actual captures.')
